using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.Rendering.Universal;

namespace ZERO
{
    /// <summary>The camera as a film camera: depth of field with a real lens (the window frame soft when the eye is on
    /// the sky, a rack focus when the gaze comes back into the cabin), bloom that swells with the light of the
    /// explosion, grain, and the lens shaken by the blast (chromatic fringe, heavier vignette). Driven every frame
    /// from the volume profile generated by the editor build (SceneBuilder.BuildVolume).</summary>
    public static class CameraFX
    {
        static DepthOfField dof; static Bloom bloom; static ChromaticAberration ca; static Vignette vig; static FilmGrain grain;
        static float focus = 5000f, focusVel;
        public static float Metering = 1f;     // exposure compensation of the camera for what it looks at
        static float meterVel;
        const float Far = 5000f;

        public static void Init(VolumeProfile p)
        {
            if (p == null) return;
            p.TryGet(out dof); p.TryGet(out bloom); p.TryGet(out ca); p.TryGet(out vig); p.TryGet(out grain);
            focus = Far;
        }

        /// <summary>Where the gaze lands: far when it goes out through a window, else the distance to the cabin.</summary>
        static float FocusTarget(Camera cam, Transform plane)
        {
            Vector3 e = plane.InverseTransformPoint(cam.transform.position);
            Vector3 d = Quaternion.Inverse(plane.rotation) * cam.transform.forward;
            if (Mathf.Abs(d.x) > 0.05f)
            {
                float side = Mathf.Sign(d.x);
                float t = (side * PlaneDef.WallX - e.x) / d.x;
                if (t > 0f)
                {
                    Vector3 h = e + d * t;
                    float zc = (h.z - PlaneDef.WindowZ0) / PlaneDef.WindowPitch;
                    float lz = (zc - Mathf.Round(zc)) * PlaneDef.WindowPitch;
                    bool inWindow = Mathf.Abs(lz) < PlaneDef.WindowW * 0.62f && Mathf.Abs(h.y - PlaneDef.WindowY) < PlaneDef.WindowH * 0.62f;
                    // only the near window opens onto the world; a window across the aisle is part of the cabin picture
                    if (inWindow && (side < 0f || t < 1.2f)) return Far;
                    return Mathf.Clamp(t, 0.5f, 6f);
                }
            }
            return Mathf.Clamp(Mathf.Abs(d.z) > 0.2f ? 2.4f : 1.2f, 0.5f, 6f);
        }

        public static void Tick(Camera cam, Transform plane, float T, float dt, bool snap)
        {
            float shake = Mathf.Clamp01(Schedule.Shake(T) + (SeatRig.I != null ? SeatRig.I.ExtraShake : 0f));
            float flash = Schedule.Flash(T);
            if (dof != null && plane != null)
            {
                // rack focus in log space: the eye refocuses in about two thirds of a second
                float want = Mathf.Log(FocusTarget(cam, plane));
                float cur = Mathf.Log(Mathf.Max(focus, 0.1f));
                cur = snap ? want : Mathf.SmoothDamp(cur, want, ref focusVel, 0.32f, 40f, dt);
                focus = Mathf.Exp(cur);
                dof.focusDistance.value = focus;
                float inside = Mathf.InverseLerp(40f, 6f, focus);
                Metering = snap ? Mathf.Lerp(1f, 1.9f, inside) : Mathf.SmoothDamp(Metering, Mathf.Lerp(1f, 1.9f, inside), ref meterVel, 0.9f, 4f, dt);
                // a real lens: the field of view sets the focal length on a 24 mm high frame
                float fl = 12f / Mathf.Tan(cam.fieldOfView * 0.5f * Mathf.Deg2Rad);
                dof.focalLength.value = Mathf.Clamp(fl, 12f, 300f);
                dof.aperture.value = 2.2f;
            }
            if (bloom != null) bloom.intensity.value = 0.55f + 0.7f * flash;
            if (ca != null) ca.intensity.value = 0.3f * shake * shake;        // only the hit of the wave bends the colours (it split the thin streaks)
            if (vig != null) vig.intensity.value = 0.2f + 0.14f * shake;
            if (grain != null) grain.intensity.value = 0f;          // no grain: video compression smears noise (MASTER_PROMPT Part 7)
            Lens(cam, T);
        }

        static readonly int idRayLight = Shader.PropertyToID("_ZRayLight"), idRayTint = Shader.PropertyToID("_ZRayTint");
        static readonly int idLens = Shader.PropertyToID("_ZLens"), idTexel = Shader.PropertyToID("_ZPostTexel");

        /// <summary>0..1 how strongly the second light pours shafts through what stands in front of it: the body from
        /// its entry into the air, the explosion from the contact (a ramp, never a flash), a long tail through the smoke.</summary>
        public static float ShaftStrength(float T)
        {
            float since = T - Schedule.ContactTime;
            if (since < 0f)
            {
                float e = Mathf.SmoothStep(0f, 1f, Mathf.InverseLerp(Schedule.EntryTime - 2f, Schedule.ContactTime, T));
                return 0.6f * e * e;
            }
            // the first seconds belong to the fireball itself (its shape must read): the shafts come back as it rises into the smoke
            float ramp = Mathf.SmoothStep(0f, 1f, Mathf.InverseLerp(1f, 16f, since));
            return Mathf.Lerp(0.6f * Mathf.Exp(-since / 2f), 1f, ramp) * (0.3f + 0.7f * Mathf.Exp(-since / 60f)) * (1f - 0.6f * ShaderGlobals.Dust(T));
        }

        /// <summary>The lens pass (ZeroPostFeature): where the second light is on screen, how strong its shafts are,
        /// and the threshold of their source.</summary>
        static void Lens(Camera cam, float T)
        {
            float w = Mathf.Max(1, cam.pixelWidth), h = Mathf.Max(1, cam.pixelHeight);
            Shader.SetGlobalVector(idTexel, new Vector4(1f / w, 1f / h, 4f / w, 4f / h));
            Vector3 eye = FloatingOrigin.ToAbs(cam.transform.position);
            Vector3 app = FloatingOrigin.ToUnity(Planet.Apparent(ShaderGlobals.LightAbs, eye));
            Vector3 vp = cam.WorldToViewportPoint(app);
            float k = ShaftStrength(T);
            // only a light in front of the lens casts shafts; they fade as it leaves the frame by more than half a frame
            float off = Mathf.Max(Mathf.Abs(vp.x - 0.5f), Mathf.Abs(vp.y - 0.5f));
            k *= vp.z > 0f ? 1f - Mathf.SmoothStep(0f, 1f, Mathf.InverseLerp(0.9f, 1.7f, off)) : 0f;
            // the source grows with the apparent size of the fireball
            float since = T - Schedule.ContactTime;
            float dist = Mathf.Max(1000f, (app - cam.transform.position).magnitude);
            float rad = since > 0f ? Schedule.FireballRadius(T) * 1.3f : 30000f;
            float angUv = Mathf.Atan(rad / dist) / (cam.fieldOfView * Mathf.Deg2Rad);
            k *= 1f - 0.7f * Mathf.SmoothStep(0f, 1f, Mathf.InverseLerp(0.12f, 0.4f, angUv));     // a source that fills the frame does not pour shafts over it
            // viewport y runs up from the bottom; the texture coordinates of the blit run down from the top on D3D
            float v = SystemInfo.graphicsUVStartsAtTop ? 1f - vp.y : vp.y;
            Shader.SetGlobalVector(idRayLight, new Vector4(vp.x, v, k, Mathf.Clamp(0.12f + 0.8f * angUv, 0.12f, 0.5f)));
            Color pc = ShaderGlobals.LightColour;
            Shader.SetGlobalVector(idRayTint, new Vector4(Mathf.Lerp(1f, pc.r, 0.7f), Mathf.Lerp(1f, pc.g, 0.7f), Mathf.Lerp(1f, pc.b, 0.7f), 0f) * 0.35f);
            Shader.SetGlobalVector(idLens, new Vector4(3.5f, 0f, 0f, 0f));
        }
    }
}
